import type { Lane } from '../config/schema.js'
import { formatTaskId } from '../registry/id.js'

const LANE_PREFIX: Record<Lane, string> = {
  docs: 'docs',
  tests: 'test',
  simple_bugs: 'fix',
  experimental: 'feat',
}

export function generateBranchName(lane: Lane, taskNumber: number, title: string): string {
  const prefix = LANE_PREFIX[lane]
  const taskId = formatTaskId(taskNumber).toLowerCase()
  const slug = slugify(title, 60)
  return `${prefix}/hackon/${taskId}-${slug}`
}

function slugify(text: string, maxLength: number): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, maxLength)
    .replace(/-+$/, '')
}
